//! The device-link ceremony construction (ADR-0192): context hash, key schedule, associated data, comparison code,
//! approval binding and the local polling id. Pure functions over bytes: no state, no I/O. The flow that uses them is
//! `flows/ceremony.rs`; the independent vectors are `verification/vectors/device-link-ceremony-vectors.json.gz`
//! (generated by `verification/prototypes/device-link-ceremony/`, replayed by `tests/device_link_vectors.rs`).
//!
//! Notation (ADR-0192 section 1): OM-CBOR is the canonical deterministic CBOR of `CANONICAL_ENCODING.md`;
//! `DS-HASH(label, body)` is the registry construction (raw 32-byte SHA-256, as `ds_hash`); HKDF is HKDF-SHA-256
//! (RFC 5869); HMAC is HMAC-SHA-256 (RFC 2104).

use super::cbor::{self, V};
use super::kdf::{hkdf_sha256, hmac_sha256};
use super::sig::ds_hash;
use zeroize::Zeroize;

/// `mac`: the two ceremony MACs (comparison code and approval binding), as `mac_in`.
pub const LBL_MAC: &str = "OM-DEVICE-LINK-CEREMONY-MAC-v1";
/// `kdf`: context hash, salt and expand info.
pub const LBL_KDF: &str = "OM-DEVICE-LINK-CEREMONY-KDF-v1";
/// `aead_ad`: associated data of every sealed ceremony message.
pub const LBL_AEAD_AD: &str = "OM-DEVICE-LINK-CEREMONY-AEAD-AD-v1";
/// `hash`: the local polling id of the response queue.
pub const LBL_MAILBOX: &str = "OM-DEVICE-LINK-CEREMONY-MAILBOX-HASH-v1";

/// The link payload version this construction defines. Version 1 (the provisional derivation) is refused.
pub const LINK_VERSION: u8 = 2;
/// Message direction in the associated data: new device to existing device, and back.
pub const ROLE_REQ: u8 = 1;
pub const ROLE_RESP: u8 = 2;
/// Role inside the MAC input, so one label serves one construction and a code can never be replayed as a binding.
pub const MAC_ROLE_CODE: u64 = 1;
pub const MAC_ROLE_BINDING: u64 = 2;

/// The four purpose keys and the public context hash. Wiped when dropped.
pub struct CeremonyKeys {
    /// `DS-HASH(LBL_KDF, CTX)`: the public transcript hash, the HKDF salt and the associated-data context.
    pub id: [u8; 32],
    pub req: [u8; 32],
    pub resp: [u8; 32],
    pub code: [u8; 32],
    pub bind: [u8; 32],
}

impl Drop for CeremonyKeys {
    fn drop(&mut self) {
        self.req.zeroize();
        self.resp.zeroize();
        self.code.zeroize();
        self.bind.zeroize();
    }
}

impl CeremonyKeys {
    /// The key a message of direction `role` is sealed under.
    pub fn for_role(&self, role: u8) -> &[u8; 32] {
        if role == ROLE_REQ {
            &self.req
        } else {
            &self.resp
        }
    }
}

/// `CTX = OM-CBOR [ 2, expiry_s, home_uri, A_cap, B_recv ]`; `home_uri` is the exact UTF-8 bytes of the link's Home.
pub fn context(expiry_s: u64, home_uri: &[u8], a_cap: &[u8], b_recv: &[u8]) -> Vec<u8> {
    cbor::encode(&V::A(vec![
        V::U(u64::from(LINK_VERSION)),
        V::U(expiry_s),
        V::B(home_uri.to_vec()),
        V::B(a_cap.to_vec()),
        V::B(b_recv.to_vec()),
    ]))
}

/// `ceremony_id = DS-HASH(LBL_KDF, CTX)`.
pub fn ceremony_id(ctx: &[u8]) -> [u8; 32] {
    ds_hash(LBL_KDF, ctx)
}

/// `PRK = HKDF-Extract(salt = ceremony_id, IKM = S)`.
pub fn prk(id: &[u8; 32], secret: &[u8]) -> [u8; 32] {
    hmac_sha256(id, secret)
}

/// `info = OM-CBOR [ LBL_KDF, purpose ]`.
pub fn expand_info(purpose: &str) -> Vec<u8> {
    cbor::encode(&V::A(vec![V::T(LBL_KDF.into()), V::T(purpose.into())]))
}

/// The key schedule: every key is bound to the Home, the expiry, the version and both capabilities by the salt, and no
/// key serves two purposes. `secret` is the one-time secret `S` of the link (at least 16 random bytes).
pub fn keys(
    expiry_s: u64,
    home_uri: &[u8],
    secret: &[u8],
    a_cap: &[u8],
    b_recv: &[u8],
) -> CeremonyKeys {
    let id = ceremony_id(&context(expiry_s, home_uri, a_cap, b_recv));
    let derive = |purpose: &str| {
        let mut out = [0u8; 32];
        hkdf_sha256(&id, secret, &expand_info(purpose), &mut out);
        out
    };
    CeremonyKeys {
        id,
        req: derive("req"),
        resp: derive("resp"),
        code: derive("code"),
        bind: derive("bind"),
    }
}

/// `AD = OM-CBOR [ LBL_AEAD_AD, ceremony_id, role ]`, role 1 for the request direction and 2 for the response direction.
pub fn aead_ad(id: &[u8; 32], role: u8) -> Vec<u8> {
    cbor::encode(&V::A(vec![
        V::T(LBL_AEAD_AD.into()),
        V::B(id.to_vec()),
        V::U(u64::from(role)),
    ]))
}

/// `MACIN(role, body) = OM-CBOR [ LBL_MAC, role, body ]`.
pub fn mac_in(role: u64, body: &[u8]) -> Vec<u8> {
    cbor::encode(&V::A(vec![
        V::T(LBL_MAC.into()),
        V::U(role),
        V::B(body.to_vec()),
    ]))
}

/// `m = HMAC(K_code, MACIN(1, request_bytes))` over the exact request bytes as the new device sent them.
pub fn code_mac(k_code: &[u8; 32], request_bytes: &[u8]) -> [u8; 32] {
    hmac_sha256(k_code, &mac_in(MAC_ROLE_CODE, request_bytes))
}

/// The number the six digits show: the big-endian u64 of `m[0..8]` modulo 1,000,000.
pub fn code_number(m: &[u8; 32]) -> u32 {
    let n = u64::from_be_bytes([m[0], m[1], m[2], m[3], m[4], m[5], m[6], m[7]]);
    (n % 1_000_000) as u32
}

/// Six digits with leading zeros ("007421").
pub fn code_digits(m: &[u8; 32]) -> String {
    format!("{:06}", code_number(m))
}

/// The same code as two groups of three ("482 913"), for a display that wants them.
pub fn code_grouped(m: &[u8; 32]) -> String {
    let d = code_digits(m);
    format!("{} {}", &d[..3], &d[3..])
}

/// The six digits both devices show for a request.
pub fn verification_code(k_code: &[u8; 32], request_bytes: &[u8]) -> String {
    code_digits(&code_mac(k_code, request_bytes))
}

/// `binding = HMAC(K_bind, MACIN(2, OM-CBOR [request_digest, approver_device_id, new_state_hash, notice_digest,
/// roster_count, history_count]))`: which request, successor and notice an approval is for.
pub fn binding(
    k_bind: &[u8; 32],
    request_digest: &[u8; 32],
    approver: &[u8],
    new_state_hash: &[u8; 32],
    notice_digest: &[u8; 32],
    roster_count: u64,
    history_count: u64,
) -> [u8; 32] {
    let body = cbor::encode(&V::A(vec![
        V::B(request_digest.to_vec()),
        V::B(approver.to_vec()),
        V::B(new_state_hash.to_vec()),
        V::B(notice_digest.to_vec()),
        V::U(roster_count),
        V::U(history_count),
    ]));
    hmac_sha256(k_bind, &mac_in(MAC_ROLE_BINDING, &body))
}

/// Constant-time equality of a received tag with a recomputed one.
pub fn tag_eq(a: &[u8], b: &[u8; 32]) -> bool {
    a.len() == b.len() && a.iter().zip(b).fold(0u8, |d, (x, y)| d | (x ^ y)) == 0
}

/// `recv_mailbox = DS-HASH(LBL_MAILBOX, B_recv)[0..16]` (a local polling id only).
pub fn recv_mailbox(b_recv: &[u8]) -> [u8; 16] {
    let h = ds_hash(LBL_MAILBOX, b_recv);
    let mut o = [0u8; 16];
    o.copy_from_slice(&h[..16]);
    o
}
